<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Top-Down Billiards</title>
<style>
  :root { color-scheme: dark; }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    min-height: 100vh;
    display: grid;
    place-items: center;
    background: #101418;
    color: #eef4ed;
    font-family: system-ui, sans-serif;
  }
  .wrap {
    width: min(96vw, 980px);
    text-align: center;
  }
  h1 {
    margin: 0 0 8px;
    font-size: clamp(20px, 3vw, 32px);
    letter-spacing: .08em;
    text-transform: uppercase;
  }
  .panel {
    display: flex;
    gap: 14px;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 10px;
    color: #cbd7ca;
    font-size: 14px;
  }
  button {
    border: 0;
    border-radius: 6px;
    padding: 9px 16px;
    color: white;
    background: #b13b32;
    font-weight: 700;
    cursor: pointer;
  }
  button:hover { background: #d24b3e; }
  .table-shell {
    padding: 18px;
    border-radius: 12px;
    background: linear-gradient(135deg, #653d22, #a76b35 48%, #4c2c19);
    box-shadow: 0 18px 45px #000a, inset 0 0 0 3px #d09654;
  }
  canvas {
    display: block;
    width: 100%;
    height: auto;
    border-radius: 5px;
    background: #175a39;
    cursor: crosshair;
    touch-action: none;
  }
  .hint {
    margin-top: 10px;
    color: #b9c9bb;
    font-size: 14px;
  }
</style>
</head>
<body>
<div class="wrap">
  <h1>Corner Pocket</h1>
  <div class="panel">
    <span id="status">Drag the cue ball backward to aim.</span>
    <button id="reset">Reset / Rack</button>
  </div>
  <div class="table-shell">
    <canvas id="table" width="900" height="500"></canvas>
  </div>
  <div class="hint">Press on the white cue ball, drag back to aim and set power, then release to shoot.</div>
</div>

<script>
(() => {
  "use strict";

  const canvas = document.getElementById("table");
  const ctx = canvas.getContext("2d");
  const status = document.getElementById("status");
  const resetButton = document.getElementById("reset");

  const W = 900, H = 500, R = 11;
  const pocketRadius = 19;
  const friction = 30;
  const maxDrag = 210;
  const powerScale = 5.0;
  let balls = [];
  let running = true;
  let dragging = false;
  let dragPoint = { x: 0, y: 0 };
  let lastTime = performance.now();

  const colors = [
    "#f6f6ed", "#e9c52c", "#2870bb", "#c63332", "#713a9d",
    "#ed8a28", "#318c50", "#8d292b", "#171717", "#e9c52c",
    "#2870bb", "#c63332", "#713a9d", "#ed8a28", "#318c50",
    "#8d292b"
  ];

  function defaultRack() {
    const rack = [];
    const cx = W * .69, cy = H / 2;
    rack.push({ x: W * .27, y: cy, vx: 0, vy: 0, cue: true });
    const spacing = R * 2.03;
    let n = 1;
    for (let col = 0; col < 5; col++) {
      const x = cx + col * spacing;
      for (let row = 0; row <= col; row++) {
        rack.push({
          x, y: cy + (row - col / 2) * spacing,
          vx: 0, vy: 0, cue: false
        });
        n++;
      }
    }
    return rack;
  }

  function reset(input) {
    const source = Array.isArray(input) ? input : defaultRack();
    balls = source.map(b => ({
      x: Number(b.x), y: Number(b.y),
      vx: Number(b.vx || 0), vy: Number(b.vy || 0),
      cue: !!b.cue, potted: false
    }));
    dragging = false;
    status.textContent = "Drag the cue ball backward to aim.";
    draw();
  }

  function pocketLocations() {
    return [
      [0, 0], [W / 2, 0], [W, 0],
      [0, H], [W / 2, H], [W, H]
    ];
  }

  function potCheck(b) {
    for (const [px, py] of pocketLocations()) {
      if (Math.hypot(b.x - px, b.y - py) <= pocketRadius) {
        b.potted = true;
        b.vx = b.vy = 0;
        return true;
      }
    }
    return false;
  }

  function step(dt) {
    if (!Number.isFinite(dt) || dt <= 0) {
      draw();
      return;
    }
    dt = Math.min(dt, 0.1);
    const count = Math.max(1, Math.ceil(dt / 0.008));
    const h = dt / count;

    for (let sub = 0; sub < count; sub++) {
      for (const b of balls) {
        if (b.potted) continue;
        b.x += b.vx * h;
        b.y += b.vy * h;
        if (potCheck(b)) continue;

        const speed = Math.hypot(b.vx, b.vy);
        if (speed > 0) {
          const ns = Math.max(0, speed - friction * h);
          if (ns === 0) b.vx = b.vy = 0;
          else {
            b.vx *= ns / speed;
            b.vy *= ns / speed;
          }
        }

        if (b.x < R) { b.x = R; if (b.vx < 0) b.vx = -b.vx; }
        if (b.x > W - R) { b.x = W - R; if (b.vx > 0) b.vx = -b.vx; }
        if (b.y < R) { b.y = R; if (b.vy < 0) b.vy = -b.vy; }
        if (b.y > H - R) { b.y = H - R; if (b.vy > 0) b.vy = -b.vy; }
      }

      for (let i = 0; i < balls.length; i++) {
        const a = balls[i];
        if (a.potted) continue;
        for (let j = i + 1; j < balls.length; j++) {
          const b = balls[j];
          if (b.potted) continue;

          let dx = b.x - a.x, dy = b.y - a.y;
          let dist = Math.hypot(dx, dy);
          const minDist = R * 2;
          if (dist === 0) { dx = minDist; dy = 0; dist = minDist; }
          if (dist >= minDist) continue;

          const nx = dx / dist, ny = dy / dist;
          const overlap = minDist - dist;
          a.x -= nx * overlap / 2; a.y -= ny * overlap / 2;
          b.x += nx * overlap / 2; b.y += ny * overlap / 2;

          const rvx = b.vx - a.vx, rvy = b.vy - a.vy;
          const closing = rvx * nx + rvy * ny;
          if (closing < 0) {
            a.vx += closing * nx;
            a.vy += closing * ny;
            b.vx -= closing * nx;
            b.vy -= closing * ny;
          }
        }
      }
    }
    draw();
  }

  function shoot(vx, vy) {
    const cue = balls.find(b => b.cue && !b.potted);
    if (cue) {
      cue.vx = Number(vx) || 0;
      cue.vy = Number(vy) || 0;
    }
    draw();
  }

  function pause() { running = false; }
  function resume() { if (!running) { running = true; lastTime = performance.now(); requestAnimationFrame(loop); } }

  function state() {
    return balls.map(b => ({
      x: b.x, y: b.y, vx: b.vx, vy: b.vy,
      potted: b.potted, cue: b.cue
    }));
  }

  window.sim = { W, H, R, reset, step, state, shoot, pause, resume };

  function pointFromEvent(e) {
    const r = canvas.getBoundingClientRect();
    return {
      x: (e.clientX - r.left) * W / r.width,
      y: (e.clientY - r.top) * H / r.height
    };
  }

  canvas.addEventListener("pointerdown", e => {
    const p = pointFromEvent(e);
    const cue = balls.find(b => b.cue && !b.potted);
    if (!cue || Math.hypot(p.x - cue.x, p.y - cue.y) > R * 1.8) return;
    const speed = Math.hypot(cue.vx, cue.vy);
    if (speed > 1) return;
    dragging = true;
    dragPoint = p;
    canvas.setPointerCapture(e.pointerId);
    pause();
    draw();
  });

  canvas.addEventListener("pointermove", e => {
    if (!dragging) return;
    dragPoint = pointFromEvent(e);
    draw();
  });

  canvas.addEventListener("pointerup", e => {
    if (!dragging) return;
    dragPoint = pointFromEvent(e);
    const cue = balls.find(b => b.cue && !b.potted);
    if (cue) {
      let dx = cue.x - dragPoint.x, dy = cue.y - dragPoint.y;
      const len = Math.hypot(dx, dy);
      if (len > 2) {
        const power = Math.min(len, maxDrag) * powerScale;
        shoot(dx / len * power, dy / len * power);
      }
    }
    dragging = false;
    resume();
  });

  resetButton.addEventListener("click", () => { reset(); resume(); });

  function draw() {
    ctx.clearRect(0, 0, W, H);

    const felt = ctx.createLinearGradient(0, 0, W, H);
    felt.addColorStop(0, "#1d7047");
    felt.addColorStop(.5, "#135637");
    felt.addColorStop(1, "#0e482e");
    ctx.fillStyle = felt;
    ctx.fillRect(0, 0, W, H);

    ctx.strokeStyle = "rgba(255,255,255,.07)";
    ctx.lineWidth = 2;
    for (let x = 25; x < W; x += 37) {
      ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x - 100, H); ctx.stroke();
    }

    ctx.fillStyle = "#090b0a";
    for (const [x, y] of pocketLocations()) {
      ctx.beginPath(); ctx.arc(x, y, pocketRadius, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = "#321c13"; ctx.lineWidth = 4; ctx.stroke();
    }

    if (dragging) {
      const cue = balls.find(b => b.cue && !b.potted);
      if (cue) {
        let dx = cue.x - dragPoint.x, dy = cue.y - dragPoint.y;
        const len = Math.hypot(dx, dy);
        if (len > 0) {
          const reach = Math.min(len, maxDrag) * 2.1;
          const ux = dx / len, uy = dy / len;
          ctx.setLineDash([9, 8]);
          ctx.strokeStyle = "#fff9c4";
          ctx.lineWidth = 2;
          ctx.beginPath();
          ctx.moveTo(cue.x, cue.y);
          ctx.lineTo(cue.x + ux * reach, cue.y + uy * reach);
          ctx.stroke();
          ctx.setLineDash([]);
          status.textContent = "Power: " + Math.round(Math.min(len / maxDrag, 1) * 100) + "%";
        }
      }
    }

    balls.forEach((b, i) => {
      if (b.potted) return;
      ctx.save();
      ctx.shadowColor = "#000b";
      ctx.shadowBlur = 5;
      ctx.shadowOffsetY = 2;
      ctx.beginPath(); ctx.arc(b.x, b.y, R, 0, Math.PI * 2);
      ctx.fillStyle = b.cue ? "#fffdf2" : colors[i % colors.length];
      ctx.fill();
      ctx.restore();

      ctx.strokeStyle = "#ffffff99";
      ctx.lineWidth = 1;
      ctx.beginPath(); ctx.arc(b.x, b.y, R, 0, Math.PI * 2); ctx.stroke();

      if (!b.cue && i >= 9) {
        ctx.strokeStyle = "#fff";
        ctx.lineWidth = 3;
        ctx.beginPath(); ctx.arc(b.x, b.y, R * .62, 0, Math.PI * 2); ctx.stroke();
      }
      if (i === 8) {
        ctx.fillStyle = "#d8b642";
        ctx.beginPath(); ctx.arc(b.x, b.y, 3, 0, Math.PI * 2); ctx.fill();
      }
    });
  }

  function loop(now) {
    if (!running) return;
    const dt = Math.min((now - lastTime) / 1000, 0.05);
    lastTime = now;
    if (!dragging) step(dt);
    requestAnimationFrame(loop);
  }

  reset();
  requestAnimationFrame(loop);
})();
</script>
</body>
</html>
